ase_value_diff`,SUM((p.`cloudbase` IS NULL)<>(g.`cloudbase` IS NULL)) AS `cloudbase_one_sided_null`,SUM(p.`dewpoint` IS NOT NULL AND g.`dewpoint` IS NOT NULL) AS `dewpoint_both_nonnull`,SUM(p.`dewpoint` IS NOT NULL AND g.`dewpoint` IS NOT NULL AND p.`dewpoint`<>g.`dewpoint`) AS `dewpoint_value_diff`,SUM((p.`dewpoint` IS NULL)<>(g.`dewpoint` IS NULL)) AS `dewpoint_one_sided_null`,SUM(p.`ET` IS NOT NULL AND g.`ET` IS NOT NULL) AS `ET_both_nonnull`,SUM(p.`ET` IS NOT NULL AND g.`ET` IS NOT NULL AND p.`ET`<>g.`ET`) AS `ET_value_diff`,SUM((p.`ET` IS NULL)<>(g.`ET` IS NULL)) AS `ET_one_sided_null`,SUM(p.`extraTemp1` IS NOT NULL AND g.`extraTemp1` IS NOT NULL) AS `extraTemp1_both_nonnull`,SUM(p.`extraTemp1` IS NOT NULL AND g.`extraTemp1` IS NOT NULL AND p.`extraTemp1`<>g.`extraTemp1`) AS `extraTemp1_value_diff`,SUM((p.`extraTemp1` IS NULL)<>(g.`extraTemp1` IS NULL)) AS `extraTemp1_one_sided_null`,SUM(p.`extraTemp2` IS NOT NULL AND g.`extraTemp2` IS NOT NULL) AS `extraTemp2_both_nonnull`,SUM(p.`extraTemp2` IS NOT NULL AND g.`extraTemp2` IS NOT NULL AND p.`extraTemp2`<>g.`extraTemp2`) AS `extraTemp2_value_diff`,SUM((p.`extraTemp2` IS NULL)<>(g.`extraTemp2` IS NULL)) AS `extraTemp2_one_sided_null`,SUM(p.`heatindex` IS NOT NULL AND g.`heatindex` IS NOT NULL) AS `heatindex_both_nonnull`,SUM(p.`heatindex` IS NOT NULL AND g.`heatindex` IS NOT NULL AND p.`heatindex`<>g.`heatindex`) AS `heatindex_value_diff`,SUM((p.`heatindex` IS NULL)<>(g.`heatindex` IS NULL)) AS `heatindex_one_sided_null`,SUM(p.`humidex` IS NOT NULL AND g.`humidex` IS NOT NULL) AS `humidex_both_nonnull`,SUM(p.`humidex` IS NOT NULL AND g.`humidex` IS NOT NULL AND p.`humidex`<>g.`humidex`) AS `humidex_value_diff`,SUM((p.`humidex` IS NULL)<>(g.`humidex` IS NULL)) AS `humidex_one_sided_null`,SUM(p.`inDewpoint` IS NOT NULL AND g.`inDewpoint` IS NOT NULL) AS `inDewpoint_both_nonnull`,SUM(p.`inDewpoint` IS NOT NULL AND g.`inDewpoint` IS NOT NULL AND p.`inDewpoint`<>g.`inDewpoint`) AS `inDewpoint_value_diff`,SUM((p.`inDew