AS `outEquiTemp_both_nonnull`,SUM(p.`outEquiTemp` IS NOT NULL AND g.`outEquiTemp` IS NOT NULL AND p.`outEquiTemp`<>g.`outEquiTemp`) AS `outEquiTemp_value_diff`,SUM((p.`outEquiTemp` IS NULL)<>(g.`outEquiTemp` IS NULL)) AS `outEquiTemp_one_sided_null`,SUM(p.`pressure` IS NOT NULL AND g.`pressure` IS NOT NULL) AS `pressure_both_nonnull`,SUM(p.`pressure` IS NOT NULL AND g.`pressure` IS NOT NULL AND p.`pressure`<>g.`pressure`) AS `pressure_value_diff`,SUM((p.`pressure` IS NULL)<>(g.`pressure` IS NULL)) AS `pressure_one_sided_null`,SUM(p.`radiation` IS NOT NULL AND g.`radiation` IS NOT NULL) AS `radiation_both_nonnull`,SUM(p.`radiation` IS NOT NULL AND g.`radiation` IS NOT NULL AND p.`radiation`<>g.`radiation`) AS `radiation_value_diff`,SUM((p.`radiation` IS NULL)<>(g.`radiation` IS NULL)) AS `radiation_one_sided_null`,SUM(p.`rain` IS NOT NULL AND g.`rain` IS NOT NULL) AS `rain_both_nonnull`,SUM(p.`rain` IS NOT NULL AND g.`rain` IS NOT NULL AND p.`rain`<>g.`rain`) AS `rain_value_diff`,SUM((p.`rain` IS NULL)<>(g.`rain` IS NULL)) AS `rain_one_sided_null`,SUM(p.`rainRate` IS NOT NULL AND g.`rainRate` IS NOT NULL) AS `rainRate_both_nonnull`,SUM(p.`rainRate` IS NOT NULL AND g.`rainRate` IS NOT NULL AND p.`rainRate`<>g.`rainRate`) AS `rainRate_value_diff`,SUM((p.`rainRate` IS NULL)<>(g.`rainRate` IS NULL)) AS `rainRate_one_sided_null`,SUM(p.`soilMoist1` IS NOT NULL AND g.`soilMoist1` IS NOT NULL) AS `soilMoist1_both_nonnull`,SUM(p.`soilMoist1` IS NOT NULL AND g.`soilMoist1` IS NOT NULL AND p.`soilMoist1`<>g.`soilMoist1`) AS `soilMoist1_value_diff`,SUM((p.`soilMoist1` IS NULL)<>(g.`soilMoist1` IS NULL)) AS `soilMoist1_one_sided_null`,SUM(p.`soilTemp1` IS NOT NULL AND g.`soilTemp1` IS NOT NULL) AS `soilTemp1_both_nonnull`,SUM(p.`soilTemp1` IS NOT NULL AND g.`soilTemp1` IS NOT NULL AND p.`soilTemp1`<>g.`soilTemp1`) AS `soilTemp1_value_diff`,SUM((p.`soilTemp1` IS NULL)<>(g.`soilTemp1` IS NULL)) AS `soilTemp1_one_sided_null`,SUM(p.`soilTemp2` IS NOT NULL AND g.`soilTemp2` IS NOT NUL